"""Logins and sessions."""
import hashlib
import secrets

SCHEMA = """
CREATE TABLE IF NOT EXISTS credentials (user_id INTEGER PRIMARY KEY REFERENCES users(id), pw_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id),
                                     created_at TEXT NOT NULL DEFAULT (datetime('now')));
"""


def setup(con):
    con.executescript(SCHEMA)


def _hash(pw):
    return hashlib.sha256(pw.encode()).hexdigest()   # demo only


def set_password(con, user_id, pw):
    con.execute("INSERT OR REPLACE INTO credentials(user_id, pw_hash) VALUES (?, ?)", (user_id, _hash(pw)))


def login(con, user_id, pw):
    row = con.execute("SELECT pw_hash FROM credentials WHERE user_id = ?", (user_id,)).fetchone()
    if row is None or row["pw_hash"] != _hash(pw):
        raise PermissionError("bad credentials")
    token = secrets.token_hex(16)
    con.execute("INSERT INTO sessions(token, user_id) VALUES (?, ?)", (token, user_id))
    return token


def current_user(con, token):
    row = con.execute("SELECT user_id FROM sessions WHERE token = ?", (token,)).fetchone()
    if row is None:
        raise PermissionError("no session")
    return row["user_id"]


def change_password(con, token, new_pw):
    set_password(con, current_user(con, token), new_pw)

