"""Customers and orders."""

SCHEMA = """
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL, phone TEXT,
                                      deleted_at TEXT);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id),
                                   shipping_name TEXT NOT NULL, shipping_address TEXT NOT NULL, total INTEGER NOT NULL);
"""


def setup(con):
    con.executescript(SCHEMA)


def add_customer(con, email, name, phone=None):
    return con.execute("INSERT INTO customers(email, name, phone) VALUES (?, ?, ?)", (email, name, phone)).lastrowid


def add_order(con, customer_id, shipping_name, shipping_address, total):
    return con.execute("INSERT INTO orders(customer_id, shipping_name, shipping_address, total) VALUES (?, ?, ?, ?)",
                       (customer_id, shipping_name, shipping_address, total)).lastrowid


def delete_customer(con, customer_id):
    con.execute("UPDATE customers SET deleted_at = datetime('now') WHERE id = ?", (customer_id,))


def active_customers(con):
    return [dict(r) for r in con.execute("SELECT id, email, name FROM customers WHERE deleted_at IS NULL")]

