import unittest

from app import crm, db


class CrmTest(unittest.TestCase):
    def setUp(self):
        self.con = db.connect()
        crm.setup(self.con)

    def test_soft_delete_hides(self):
        cid = crm.add_customer(self.con, "jan@example.com", "Jan Kowalski")
        crm.delete_customer(self.con, cid)
        self.assertEqual(crm.active_customers(self.con), [])

    def test_orders_kept(self):
        cid = crm.add_customer(self.con, "jan@example.com", "Jan Kowalski")
        crm.add_order(self.con, cid, "Jan Kowalski", "ul. Polna 1, Lublin", 100)
        self.assertEqual(self.con.execute("SELECT COUNT(*) FROM orders").fetchone()[0], 1)


if __name__ == "__main__":
    unittest.main()
